343	    private static boolean isBlank(String value) {
344	        return value == null || value.isBlank();
345	    }
346	
347	    /**
348	     * Reads the {@code Idempotency-Key} header from the current request, or {@code null} when the
349	     * header is absent, blank, or there is no bound request. A present, non-blank value is trimmed.
350	     *
351	     * @return the trimmed idempotency key, or {@code null} when none was supplied
352	     */
353	    private static String currentIdempotencyKey() {
354	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
355	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
356	            return null;
357	        }
358	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
359	        return isBlank(key) ? null : key.trim();
360	    }
361	
362	    /**
363	     * The set of disposable email domains that owners may not register with. Compared
364	     * case-insensitively against the domain part of the supplied email.
365	     */
366	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
367	        "mailinator.com", "tempmail.com", "guerrillamail.com");
368	
369	    /**
370	     * Rejects an owner whose email domain is on the disposable-domain blocklist
371	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is optional:
372	     * a {@code null} or blank value, or one without an {@code '@'} domain part, is accepted here (the
373	     * {@code @Email} Bean Validation constraint governs format). The domain is compared
374	     * case-insensitively; the stored email is already lower-cased.
375	     *
376	     * @param email the owner's email (may be {@code null})
377	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
378	     */
379	    private static void validateEmailDomain(String email) {
380	        if (isBlank(email)) {
381	            return;
382	        }
383	        int at = email.lastIndexOf('@');
384	        if (at < 0) {
385	            return;
386	        }
387	        String domain = email.substring(at + 1).trim().toLowerCase(java.util.Locale.ROOT);
388	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
389	            throw new DisposableEmailDomainException(email);
390	        }
391	    }
392	
393	    /**
394	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
395	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
396	     */
397	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
398	        "NSW", new int[] {2000, 2099},
399	        "VIC", new int[] {3000, 3099},
400	        "QLD", new int[] {4000, 4099});
401	
402	    /**
403	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
404	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
405	     * present, the value has already passed the 4-digit format check (Bean Validation on the
406	     * request body); this enforces that it falls within the inclusive range for the city's region
407	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
408	     *
409	     * @param postcode the supplied postcode (may be {@code null})
410	     * @param region the owner's locality/region derived from its city
411	     * @throws InvalidPostcodeException if the postcode is out of range for the region
412	     */
413	    private static void validatePostcode(String postcode, String region) {
414	        if (isBlank(postcode)) {
415	            return;
416	        }
417	        int[] range = REGION_POSTCODES.get(region);
418	        if (range == null) {
419	            return;
420	        }
421	        int value;
422	        try {
423	            value = Integer.parseInt(postcode);
424	        }
425	        catch (NumberFormatException e) {
426	            throw new InvalidPostcodeException(postcode);
427	        }
428	        if (value < range[0] || value > range[1]) {
429	            throw new InvalidPostcodeException(postcode);
430	        }
431	    }
432	
433	    /**
434	     * Normalizes a street address into the canonical form stored on and returned for a newly
435	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
436	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
437	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
438	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
439	     * value is what gets persisted, echoed back, and used for every address comparison (household
440	     * duplicate detection and the shared household identifier).
441	     *
442	     * @param rawAddress the address value as supplied by the client
443	     * @return the normalized address (possibly empty, never {@code null})
444	     */
445	    private static String normalizeAddress(String rawAddress) {
446	        if (rawAddress == null) {
447	            return "";
448	        }
449	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
450	        if (collapsed.isEmpty()) {
451	            return "";
452	        }
453	        String[] tokens = collapsed.split(" ");
454	        StringBuilder sb = new StringBuilder(collapsed.length());
455	        for (int i = 0; i < tokens.length; i++) {
456	            String token = tokens[i];
457	            switch (token) {
458	                case "ST" -> token = "STREET";
459	                case "RD" -> token = "ROAD";
460	                case "AVE" -> token = "AVENUE";
461	                default -> { }
462	            }
463	            if (i > 0) {
464	                sb.append(' ');
465	            }
466	            sb.append(token);
467	        }
468	        return sb.toString();
469	    }
470	
471	    /**
472	     * Builds the customer code assigned to a newly created owner. The code is formatted
473	     * {@code <REGION>-<HASH8>} where {@code REGION} is the region derived from the owner's postcode
474	     * (see {@link Owner#getRegion()}) and {@code HASH8} is the first 8 upper-case hex characters of
475	     * the SHA-256 digest of the owner's normalized (E.164) telephone concatenated with its last
476	     * name (e.g. {@code NSW-1A2B3C4D}). No sequence number is involved, so the code depends only on
477	     * the owner's own region and identity.
478	     *
479	     * @param owner the owner being created, with telephone already normalized and postcode/city set
480	     * @return the customer code to assign
481	     */
482	    private static String customerCodeFor(Owner owner) {
483	        return owner.getRegion() + "-" + telephoneNameHash(owner.getTelephone(), owner.getLastName());
484	    }
485	
486	    /**
487	     * De-duplicates a freshly computed customer code against the codes already assigned to existing
488	     * owners. When no existing owner carries the given code it is returned unchanged; otherwise the
489	     * smallest suffix {@code -<n>} with {@code n >= 2} that yields a code no existing owner holds is
490	     * appended, guaranteeing distinct owners always receive distinct customer codes.
491	     *
492	     * @param customerCode the customer code computed for the owner being created
493	     * @return the de-duplicated customer code, unique among existing owners
494	     */
495	    private String deduplicateCustomerCode(String customerCode) {
496	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
497	            .map(Owner::getCustomerCode)
498	            .filter(java.util.Objects::nonNull)
499	            .collect(java.util.stream.Collectors.toSet());
500	        if (!existing.contains(customerCode)) {
501	            return customerCode;
502	        }
503	        int n = 2;
504	        while (existing.contains(customerCode + "-" + n)) {
505	            n++;
506	        }
507	        return customerCode + "-" + n;
508	    }
509	
510	    /**
511	     * Computes the {@code HASH8} segment of the customer code: the first 8 upper-case hex
512	     * characters of the SHA-256 digest of the normalized (E.164) telephone concatenated with the
513	     * last name.
514	     *
515	     * @param normalizedTelephone the owner's telephone in E.164 form
516	     * @param lastName the owner's last name
517	     * @return the 8-character upper-case hex hash
518	     */
519	    private static String telephoneNameHash(String normalizedTelephone, String lastName) {
520	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
521	            + (lastName == null ? "" : lastName);
522	        try {
523	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
524	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
525	            StringBuilder sb = new StringBuilder(digest.length * 2);
526	            for (byte b : digest) {
527	                sb.append(String.format("%02x", b));
528	            }
529	            return sb.substring(0, 8).toUpperCase(java.util.Locale.ROOT);
530	        }
531	        catch (java.security.NoSuchAlgorithmException e) {
532	            throw new IllegalStateException("SHA-256 not available", e);
533	        }
534	    }
535	
536	    /**
537	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
538	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
539	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
540	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
541	     * the national number must match the country code: {@code +61} requires 9 national digits and
542	     * {@code +1} requires 10.
543	     *
544	     * @param rawTelephone the telephone value as supplied by the client
545	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
546	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
547	     */
548	    private static String normalizeTelephone(String rawTelephone) {
549	        if (rawTelephone == null) {
550	            throw new InvalidTelephoneException(rawTelephone);
551	        }
552	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
553	        String e164;
554	        if (cleaned.startsWith("+")) {
555	            String digits = cleaned.substring(1);
556	            if (!digits.matches("[0-9]+")) {
557	                throw new InvalidTelephoneException(rawTelephone);
558	            }
559	            e164 = "+" + digits;
560	        } else {
561	            if (!cleaned.matches("[0-9]+")) {
562	                throw new InvalidTelephoneException(rawTelephone);
563	            }
564	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
565	            e164 = "+61" + national;
566	        }
567	        int digitCount = e164.length() - 1;
568	        if (digitCount < 8 || digitCount > 15) {
569	            throw new InvalidTelephoneException(rawTelephone);
570	        }
571	        if (e164.startsWith("+61")) {
572	            if (e164.length() - "+61".length() != 9) {
573	                throw new InvalidTelephoneException(rawTelephone);
574	            }
575	        }
576	        else if (e164.startsWith("+1")) {
577	            if (e164.length() - "+1".length() != 10) {
578	                throw new InvalidTelephoneException(rawTelephone);
579	            }
580	        }
581	        return e164;
582	    }
583	
584	    /**
585	     * Determines whether any existing owner already carries the given identity key. The identity key
586	     * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) is the single value
587	     * all duplicate detection is based on, so two owners collide only when their whole identity keys
588	     * are equal.
589	     *
590	     * @param identityKey the identity key of the owner being created
591	     * @return {@code true} if another owner already has the same identity key
592	     */
593	    private boolean isIdentityKeyInUse(String identityKey) {
594	        return this.clinicService.findAllOwners().stream()
595	            .filter(existing -> !existing.isDeleted())
596	            .map(Owner::getIdentityKey)
597	            .anyMatch(identityKey::equals);
598	    }
599	
600	    /**
601	     * Finds an existing owner that the owner being created is a possible (soft) duplicate of: one
602	     * that shares the same last name (compared case-insensitively, whitespace-collapsed) and the
603	     * same postcode but carries a <em>different</em> telephone. Such a create is not rejected as a
604	     * hard duplicate, but is flagged. An owner with no postcode can never be a soft duplicate. When
605	     * several owners match, the earliest (lowest id) is returned so the result is deterministic.
606	     *
607	     * @param owner the owner being created (telephone already normalized, postcode set)
608	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
609	     */
610	    private Integer possibleDuplicateOf(Owner owner) {
611	        if (isBlank(owner.getPostcode())) {
612	            return null;
613	        }
614	        String normalizedLastName = normalizeIdentity(owner.getLastName());
615	        return this.clinicService.findAllOwners().stream()
616	            .filter(existing -> existing.getId() != null
617	                && !existing.isDeleted()
618	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
619	                && owner.getPostcode().equals(existing.getPostcode())
620	                && !java.util.Objects.equals(owner.getTelephone(), existing.getTelephone()))
621	            .map(Owner::getId)
622	            .min(Integer::compareTo)
623	            .orElse(null);
624	    }
625	
626	    /**
627	     * Counts how many existing owners already share the given first name and last name with the
628	     * owner being created. Both names are compared case-insensitively (after trimming and
629	     * collapsing runs of whitespace). The count reflects the state before the new owner is
630	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
631	     *
632	     * @param firstName the first name of the owner being created
633	     * @param lastName the last name of the owner being created
634	     * @return the number of existing owners sharing the same first and last name
635	     */
636	    private int namesakeCount(String firstName, String lastName) {
637	        String normalizedFirstName = normalizeIdentity(firstName);
638	        String normalizedLastName = normalizeIdentity(lastName);
639	        return (int) this.clinicService.findAllOwners().stream()
640	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
641	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
642	            .count();
643	    }
644	
645	    /**
646	     * Counts how many members the owner being created belongs to in its household, including
647	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
648	     * the new owner is not yet persisted, so its own membership is added to the existing count.
649	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
650	     * household of one.
651	     *
652	     * @param householdId the shared household identifier assigned to the owner being created, or
653	     *                    {@code null} if the owner does not share a household
654	     * @return the number of household members after this create (at least 1)
655	     */
656	    private int householdSizeAfterCreate(String householdId) {
657	        if (householdId == null) {
658	            return 1;
659	        }
660	        long existing = this.clinicService.findAllOwners().stream()
661	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
662	            .count();
663	        return (int) existing + 1;
664	    }
665	
666	    /**
667	     * The maximum number of owners permitted in a single city. Once a city already contains this
668	     * many owners it is considered full and no further owners may be created there.
669	     */
670	    private static final int CITY_CAPACITY = 50;
671	
672	    /**
673	     * Determines whether the given city has already reached its capacity, i.e. already contains
674	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
675	     * collapsing runs of whitespace to a single space and trimming.
676	     *
677	     * @param city the city of the owner being created
678	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
679	     */
680	    private boolean isCityAtCapacity(String city) {
681	        String normalizedCity = normalizeIdentity(city);
682	        long count = this.clinicService.findAllOwners().stream()
683	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
684	            .count();
685	        return count >= CITY_CAPACITY;
686	    }
687	
688	    /**
689	     * The maximum number of owners that may be created on any single day. Once this many owners
690	     * already carry a {@code registrationDate} of the current day, no further owners may be created
691	     * that day.
692	     */
693	    private static final int DAILY_REGISTRATION_LIMIT = 100;
694	
695	    /**
696	     * Determines whether the daily registration limit has already been reached, i.e. whether
697	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
698	     * their {@code registrationDate}.
699	     *
700	     * @param date the current day
701	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
702	     *         registered on the given date
703	     */
704	    /**
705	     * The fixed public holidays that the business-day roll skips. A registration date landing on
706	     * any of these is rolled forward, exactly as it is for a weekend.
707	     */
708	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
709	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
710	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
711	        LocalDate.parse("2026-12-28"));
712	
713	    /**
714	     * Rolls a registration date forward onto a business day. A date that already falls on a
715	     * weekday which is not a public holiday is returned unchanged; a Saturday, Sunday or listed
716	     * public holiday is rolled forward, one day at a time, until the next non-weekend,
717	     * non-holiday day is reached. This adjusted date is what gets stored as the
718	     * {@code registrationDate} and drives everything derived from it (the fiscal year, the
719	     * membership number's fiscal-year segment, the daily create-limit).
720	     *
721	     * @param date the effective registration date (supplied by the client or defaulted to the
722	     *             server's current date)
723	     * @return the same date if it is a business day, otherwise the next business day that is
724	     *         neither a weekend nor a public holiday
725	     */
726	    private static LocalDate toBusinessDay(LocalDate date) {
727	        while (isNonBusinessDay(date)) {
728	            date = date.plusDays(1);
729	        }
730	        return date;
731	    }
732	
733	    private static boolean isNonBusinessDay(LocalDate date) {
734	        DayOfWeek dayOfWeek = date.getDayOfWeek();
735	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY
736	            || PUBLIC_HOLIDAYS.contains(date);
737	    }
738	
739	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
740	        long count = this.clinicService.findAllOwners().stream()
741	            .filter(existing -> date.equals(existing.getRegistrationDate()))
742	            .count();
743	        return count >= DAILY_REGISTRATION_LIMIT;
744	    }
745	
746	    /**
747	     * The number of owners that may be created on a single day before the bulk-signup warning is
748	     * raised. Once <em>more than</em> this many owners already carry the current business day as
749	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
750	     */
751	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
752	
753	    /**
754	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
755	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
756	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
757	     *
758	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
759	     *         registered on today's business day
760	     */
761	    private boolean isBulkSignupWarning() {
762	        LocalDate today = toBusinessDay(LocalDate.now());
763	        long count = this.clinicService.findAllOwners().stream()
764	            .filter(existing -> today.equals(existing.getRegistrationDate()))
765	            .count();
766	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
767	    }
768	
769	    /**
770	     * Determines whether the owner being created joins an existing household, i.e. some other owner
771	     * already carries the same computed {@code householdId} (equivalently, shares its normalized last
772	     * name and postcode). An owner with no postcode is never treated as joining a household, mirroring
773	     * the soft-duplicate rule that an owner with no postcode can never match one.
774	     *
775	     * @param owner the owner being created, with {@code householdId} already computed
776	     * @return {@code true} if another owner already belongs to the same household
777	     */
778	    private boolean isHouseholdInUse(Owner owner) {
779	        if (isBlank(owner.getPostcode())) {
780	            return false;
781	        }
782	        String householdId = owner.getHouseholdId();
783	        return this.clinicService.findAllOwners().stream()
784	            .anyMatch(existing -> existing.getId() != null
785	                && !existing.isDeleted()
786	                && householdId.equals(existing.getHouseholdId()));
787	    }
788	
789	    /**
790	     * Derives the stable household identifier for a given last name and postcode. The value is the
791	     * first 12 upper-case hex characters of the SHA-256 digest of {@code normalizedLastName + '|' +
792	     * postcode}, so it is deterministic across calls and identical for every owner sharing the same
793	     * normalized last name and postcode — they belong to the same household automatically.
794	     *
795	     * @param lastName the last name of the household
796	     * @param postcode the postcode of the household (may be {@code null})
797	     * @return the deterministic household identifier
798	     */
799	    private static String householdIdFor(String lastName, String postcode) {
800	        String key = normalizeIdentity(lastName) + "|" + (postcode == null ? "" : postcode);
801	        try {
802	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
803	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
804	            StringBuilder sb = new StringBuilder(digest.length * 2);
805	            for (byte b : digest) {
806	                sb.append(String.format("%02x", b));
807	            }
808	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
809	        }
810	        catch (java.security.NoSuchAlgorithmException e) {
811	            throw new IllegalStateException("SHA-256 not available", e);
812	        }
813	    }
814	
815	    /**
816	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
817	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
818	     * single space, and the result is lower-cased.
819	     *
820	     * @param value the raw field value
821	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
822	     */
823	    private static String normalizeIdentity(String value) {
824	        if (value == null) {
825	            return "";
826	        }
827	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
828	    }
829	}
