257	    /**
258	     * A single Luhn check digit (0-9) computed over the digits contained in the
259	     * {@link #customerCode}. Non-digit characters in the code are ignored; the standard Luhn
260	     * algorithm doubles every second digit from the right (subtracting 9 when the result exceeds
261	     * 9) and the check digit is {@code (10 - (sum % 10)) % 10}. {@code null} until a customer code
262	     * is assigned.
263	     */
264	    @Transient
265	    public Integer getCheckDigit() {
266	        if (this.customerCode == null) {
267	            return null;
268	        }
269	        int sum = 0;
270	        boolean dbl = true;
271	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
272	            char c = this.customerCode.charAt(i);
273	            if (c < '0' || c > '9') {
274	                continue;
275	            }
276	            int d = c - '0';
277	            if (dbl) {
278	                d *= 2;
279	                if (d > 9) {
280	                    d -= 9;
281	                }
282	            }
283	            sum += d;
284	            dbl = !dbl;
285	        }
286	        return (10 - (sum % 10)) % 10;
287	    }
