330	    /**
331	     * The owner's membership points, derived from the owner's own fields. Points start at 0 and
332	     * accumulate: 2 when an email is present, 1 when the owner has no namesakes ({@code namesakeCount}
333	     * is 0), 2 when the owner belongs to a household of 3 or more members ({@code householdSize} is at
334	     * least 3), and 3 when the owner's tenure — the number of elapsed fiscal years from
335	     * {@link #registrationDate} to today, the fiscal year starting on 1 July — exceeds one. Because
336	     * a newly created owner registers in the current fiscal year and so has zero tenure, and joins a
337	     * household of at most itself unless others already share it, a new owner's points reflect only the
338	     * factors captured at creation time.
339	     */
340	    @Transient
341	    public Integer getMembershipPoints() {
342	        int points = 0;
343	        boolean hasEmail = this.email != null && !this.email.isBlank();
344	        if (hasEmail) {
345	            points += 2;
346	        }
347	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
348	        if (noNamesakes) {
349	            points += 1;
350	        }
351	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
352	        if (largeHousehold) {
353	            points += 2;
354	        }
355	        boolean longTenure = this.registrationDate != null
356	            && (fiscalYearStart(LocalDate.now()) - fiscalYearStart(this.registrationDate)) > 1;
357	        if (longTenure) {
358	            points += 3;
359	        }
360	        return points;
361	    }
