363	    /**
364	     * The owner's membership level, a number from 1 to 4, derived from {@link #getMembershipPoints()}:
365	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more
366	     * points.
367	     */
368	    @Transient
369	    public Integer getMembershipLevel() {
370	        int points = getMembershipPoints();
371	        if (points <= 1) {
372	            return 1;
373	        }
374	        if (points <= 3) {
375	            return 2;
376	        }
377	        if (points <= 5) {
378	            return 3;
379	        }
380	        return 4;
381	    }
