411	    /**
412	     * The owner's locality: the {@code REGION} segment of its {@link #customerCode} (everything
413	     * before the first {@code '-'}). Because the customer code is {@code <REGION>-<HASH8>} with
414	     * {@code REGION} derived from the postcode, the locality now simply reads that region back off
415	     * the identity. Returns {@code UNKNOWN} until a customer code is assigned.
416	     */
417	    @Transient
418	    public String getLocality() {
