437	    /** Region whose postcode range contains the given postcode, or {@code null} when none does. */
438	    private static String regionForPostcode(String postcode) {
439	        if (postcode == null) {
440	            return null;
441	        }
442	        int value;
443	        try {
444	            value = Integer.parseInt(postcode.trim());
445	        }
446	        catch (NumberFormatException ex) {
447	            return null;
448	        }
449	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
450	            int[] range = entry.getValue();
451	            if (value >= range[0] && value <= range[1]) {
452	                return entry.getKey();
453	            }
454	        }
455	        return null;
456	    }
