458	    /**
459	     * The owner's identity key, the single derived value all duplicate detection is based on. It is
460	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
461	     * is the stored E.164 value, the email is the stored lower-cased value (empty when absent) and
462	     * the household segment is the deterministic {@code householdId} derived from the last name and
463	     * postcode (empty only when no household id has been assigned). Two owners are duplicates only
464	     * when their whole identity keys are equal.
465	     */
466	    @Transient
467	    public String getIdentityKey() {
468	        String telephonePart = this.telephone == null ? "" : this.telephone;
469	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
470	        String householdPart = this.householdId == null ? "" : this.householdId;
471	        return telephonePart + "|" + emailPart + "|" + householdPart;
472	    }
