561	    /**
562	     * Return the Pet with the given name, or null if none found for this Owner.
563	     *
564	     * @param name to test
565	     * @return true if pet name is already in use
566	     */
567	    public Pet getPet(String name) {
568	        return getPet(name, false);
569	    }
570	
571	    /**
572	     * Return the Pet with the given name, or null if none found for this Owner.
573	     *
574	     * @param name to test
575	     * @return true if pet name is already in use
576	     */
577	    public Pet getPet(String name, boolean ignoreNew) {
578	        name = name.toLowerCase();
579	        for (Pet pet : getPetsInternal()) {
580	            if (!ignoreNew || !pet.isNew()) {
581	                String compName = pet.getName();
582	                compName = compName.toLowerCase();
583	                if (compName.equals(name)) {
